import pathlib,json,html
R=pathlib.Path.cwd();out=R/'output/impostors-30-journeys';rows=json.loads((out/'journeys.json').read_text());e=html.escape; cards=[]
for x in rows:
 s=x['settings']; src=x['source']; name=src['name'] if src else 'One Set, Three Displays — provisional';img=next((f for f in (src or {}).get('files',[]) if '-4x5' in f),None)
 media=f'<img loading="lazy" src="/{e(img)}" alt="{e(name)}">' if img else '<p>30th concept awaiting confirmation. No selected ad file.</p>'
 cards.append(f'''<article data-search="{e(x['id']+' '+name+' '+s['hero_body'])}"><div>{media}</div><div><small>{x['id']} · {e(x['status'].replace('_',' '))}</small><h2>{e(name)}</h2><h3>{e(s['hero_title']+' '+s['hero_title_accent'])}</h3><p>{e(s['hero_body'])}</p><p><b>Journey:</b> {e(' → '.join(x['order']))} → customer proof → FAQs → {e(s['final_title'])}</p><button data-page="pages/{x['slug']}.html">Review page</button> <a href="pages/{x['slug']}.html" target="_blank">Open full page</a><details><summary>Supporting story</summary><h3>{e(s['story_title'])}</h3><p>{e(s['story_body'])}</p><h3>{e(s['final_title'])}</h3><p>{e(s['final_body'])}</p></details></div></article>''')
(out/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Little Impostors · Ad-to-page review</title><style>*{box-sizing:border-box}body{margin:0;background:#faf5f0;color:#30263b;font:16px/1.6 system-ui}header,main{max-width:1350px;margin:auto;padding:28px}h1{font-size:48px;line-height:1.1}h2{font-size:27px}h3{font-size:23px}article{display:grid;grid-template-columns:36% 1fr;gap:32px;background:white;border:1px solid #e7dce8;border-radius:20px;padding:24px;margin:24px 0}img{width:100%;border-radius:14px}button{background:#523360;color:white;padding:13px 20px;border:0;border-radius:10px;font:inherit;cursor:pointer}a{color:#523360}input{width:100%;padding:16px;border:1px solid #ccc;border-radius:10px;font:inherit}dialog{width:96vw;height:94vh;max-width:none;max-height:none;padding:0;border:0;background:#ede5ef}dialog::backdrop{background:#21182dcc}.bar{display:flex;gap:12px;padding:12px}iframe{height:calc(100% - 75px);width:100%;max-width:100%;display:block;margin:auto;border:0;background:white}article[hidden]{display:none}details{margin-top:20px}@media(max-width:650px){article{grid-template-columns:1fr}h1{font-size:36px}header,main{padding:16px}}</style><header><small>ZENKAI · LITTLE IMPOSTORS · LOCAL REVIEW</small><h1>Every ad starts a story.<br>Each page carries it home.</h1><p>30 templates using the Mimikyu Collection design. 29 concepts are present in the supplied folder; C05 is provisional pending confirmation. Each page has distinct opening, supporting story, closing copy, and an appropriate component sequence.</p><p>Local previews only. Checkout is disabled. Campaign publication and the $1,500 budget change are pending page review and launch verification.</p><input id="search" aria-label="Search concepts" placeholder="Find a concept, ID, or phrase"></header><main>'''+''.join(cards)+'''</main><dialog><div class="bar"><button id="mobile">Mobile</button><button id="desktop">Desktop</button><button id="close">Close</button></div><iframe title="Landing page preview"></iframe></dialog><script>const d=document.querySelector('dialog'),f=document.querySelector('iframe');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{f.src=b.dataset.page;d.showModal()});document.querySelector('#mobile').onclick=()=>f.style.width='390px';document.querySelector('#desktop').onclick=()=>f.style.width='100%';document.querySelector('#close').onclick=()=>d.close();document.querySelector('#search').oninput=e=>document.querySelectorAll('article').forEach(a=>a.hidden=!a.dataset.search.toLowerCase().includes(e.target.value.toLowerCase()));</script></html>''')
